query:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?name ?birthPlace WHERE {
  VALUES (?occupation) { ({{OCCUPATION}}) }

  ?person a dbo:Person ;
          rdfs:label ?name ;
          dbo:occupation ?occupation ;
          dbo:birthPlace ?birthPlace .

  FILTER(LANG(?name) = "en")
}
LIMIT {{MAX_RESULTS}}
